LITE_FIELDS = ('vod_id', 'vod_name', 'type_id', 'type_name', 'vod_year',
               'vod_area', 'vod_score', 'vod_remarks', 'vod_tags')

def lite(v, keep_content=False):
    d = {k: v.get(k) for k in LITE_FIELDS}
    if keep_content:
        d['vod_content'] = v.get('vod_content', '')
    return d

# --------------------------------------------------------------------------
# 鉴权（简易 token）
# --------------------------------------------------------------------------
def make_token(uid):
    exp = int(time.time()) + 7 * 24 * 3600
    body = '%s.%d' % (uid, exp)
    sig = hmac.new(SECRET, body.encode(), hashlib.sha256).hexdigest()[:32]
    return base64.urlsafe_b64encode(('%s.%s' % (body, sig)).encode()).decode()

def verify_token(tok):
    try:
        raw = base64.urlsafe_b64decode(tok.encode()).decode()
        uid, exp, sig = raw.rsplit('.', 2)
        good = hmac.new(SECRET, ('%s.%s' % (uid, exp)).encode(), hashlib.sha256).hexdigest()[:32]
        if not hmac.compare_digest(sig, good) or int(exp) < time.time():
            return None
        return uid
    except Exception:
        return None

def hash_pw(pw, salt=None):
    salt = salt or uuid.uuid4().hex[:12]
    h = hashlib.pbkdf2_hmac('sha256', pw.encode(), salt.encode(), 120000).hex()
    return '%s$%s' % (salt, h)

def check_pw(pw, stored):
    try:
        salt, _ = stored.split('$', 1)
        return hmac.compare_digest(hash_pw(pw, salt), stored)
    except Exception:
        return False

# --------------------------------------------------------------------------
# 嗅探实现（服务端演示：抓取页面并提取媒体地址）
# --------------------------------------------------------------------------
MEDIA_RE = re.compile(r'''https?://[^\s"'<>\\]+?\.(?:m3u8|mp4|flv|mkv|ts)(?:\?[^\s"'<>\\]*)?''', re.I)
IFRAME_RE = re.compile(r'''<iframe[^>]+src=["']([^"']+)["']''', re.I)

def sniff_page(url):
    """抓取网页，提取可能的媒体直链 / iframe。真实嗅探源用 JS 在 WebView 内完成。"""
    req = Request(url, headers={'User-Agent': 'Mozilla/5.0 (VidNest/1.0) AppleWebKit/537.36'})
    with urlopen(req, timeout=12) as r:
        html = r.read(2_000_000).decode('utf-8', 'ignore')
    found = []
    for m in MEDIA_RE.findall(html):
        if m not in found:
            found.append(m)
    iframes = list(dict.fromkeys(IFRAME_RE.findall(html)))[:10]
    return {'playUrl': found[0] if found else '', 'mediaList': found[:30], 'iframes': iframes}

