class Api:
    """业务逻辑层。"""
    @staticmethod
    def library(): return cache_get('library', lambda: load('library', []))
    @staticmethod
    def sources(): return cache_get('sources', lambda: load('sources', seed_sources()))

    @staticmethod
    def types():
        return TYPES

    @staticmethod
    def list_resources(q):
        lib = Api.library()
        tid = int(q.get('type_id', ['0'])[0] or 0)
        area = q.get('area', [''])[0]
        year = q.get('year', [''])[0]
        order = q.get('order', [''])[0]  # score / new / hot
        page = max(1, int(q.get('page', ['1'])[0] or 1))
        limit = min(50, int(q.get('limit', ['20'])[0] or 20))
        # 顶级分类 -> 包含其子分类
        ids = {tid}
        if tid:
            for t in TYPES:
                if t['type_pid'] == tid:
                    ids.add(t['type_id'])
        data = [v for v in lib if (not tid or v['type_id'] in ids or v['type_id'] == tid)]
        if area: data = [v for v in data if v.get('vod_area') == area]
        if year: data = [v for v in data if str(v.get('vod_year')) == year]
        if order == 'score': data.sort(key=lambda x: -x.get('vod_score', 0))
        elif order == 'new': data.sort(key=lambda x: -x['vod_id'])
        else: data.sort(key=lambda x: -x['vod_id'])
        total = len(data)
        start = (page - 1) * limit
        return {'code': 1, 'msg': '数据列表', 'page': page,
                'pagecount': max(1, (total + limit - 1) // limit),
                'limit': limit, 'total': total, 'list': [lite(v) for v in data[start:start + limit]]}

    @staticmethod
    def detail(vid):
        for v in Api.library():
            if v['vod_id'] == int(vid):
                d = dict(v)
                d['poster'] = '/poster/%d.svg' % v['vod_id']
                d['sources'] = [{'id': 'openlib', 'name': '开源影视演示源', 'note': '采集源',
                                 'episodes': v['episodes']}]
                return {'code': 1, 'data': d}
        return {'code': 0, 'msg': '资源不存在'}

    @staticmethod
    def search(q):
        wd = (q.get('wd', [''])[0] or '').strip()
        if not wd: return {'code': 1, 'list': []}
        kw = wd.lower()
        res = [v for v in Api.library()
               if kw in v['vod_name'].lower() or any(kw in t.lower() for t in v.get('vod_tags', []))
               or kw in v.get('vod_content', '').lower() or kw in v.get('type_name', '').lower()]
        return {'code': 1, 'wd': wd, 'list': [lite(v) for v in res]}

    @staticmethod
    def byids(ids):
        lib = {v['vod_id']: v for v in Api.library()}
        return {'code': 1, 'list': [lite(lib[i]) for i in ids if i in lib]}

    @staticmethod
    def home():
        def build():
            h = load('home', {'banners': [], 'sections': [], 'topics': []})
            return {
                'banners': [lite(v, True) for v in h.get('banners', [])],
                'sections': [dict(s, videos=[lite(v) for v in s.get('videos', [])])
                             for s in h.get('sections', [])],
                'topics': h.get('topics', []),
            }
        return cache_get('home', build)

    @staticmethod
    def hotwords():
        return ['Sintel', 'Big Buck Bunny', 'Tears of Steel', '开源动画', '汽车', '纪录片', '科幻', 'Blender']

# ==========================================================================
# 真实播放源对接：通用采集接口（苹果 CMS / TVBox 规范）+ 网页嗅探
# ==========================================================================
UA = ('Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 '
      '(KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36')

def http_get(url, timeout=15):
    req = Request(url, headers={'User-Agent': UA, 'Accept': '*/*'})
    with urlopen(req, timeout=timeout) as r:
        raw = r.read(3_000_000)
    for enc in ('utf-8', 'gbk', 'gb18030'):
        try:
            return raw.decode(enc)
        except Exception:
            pass
    return raw.decode('utf-8', 'ignore')

class CollectError(Exception):
    """采集源返回了非 JSON / 明确拒绝，给出人话错误。"""

def collect_query(api, params, timeout=15):
    """按苹果 CMS 采集规范请求：?ac=videolist&pg=1&t=&wd="""
    sep = '&' if '?' in api else '?'
    txt = http_get(api + sep + urlencode(params), timeout=timeout)
    t = (txt or '').strip()
    if not t.startswith('{'):
        hint = t[:40] if t else '空响应'
        if '搜索' in t:
            raise CollectError('该源不支持关键词搜索（可改用分类浏览）')
        raise CollectError('返回非 JSON：%s' % hint)
    try:
        return json.loads(t)
    except Exception:
        raise CollectError('JSON 解析失败')

def norm_play_url(s):
    """'第01集$http://a.m3u8#第02集$http://b.m3u8' -> [{name,url},...]"""
    eps, seen = [], set()
    for part in (s or '').split('#'):
        part = part.strip()
        if not part:
            continue
        if '$' in part:
            name, url = part.split('$', 1)
        else:
            name, url = '正片', part
        url = url.strip()
        if url.startswith('http') and url not in seen:
            seen.add(url)
            eps.append({'name': (name.strip() or '第%d集' % (len(eps) + 1)), 'url': url})
    return eps

def norm_vod(item, src):
    """把采集源原始条目规范化成影巢结构，并套用类型映射。"""
    mapping = {str(k): v for k, v in (src.get('mappings') or {}).items()}
    raw_tid = str(item.get('type_id', ''))
    mapped = mapping.get(raw_tid)
    return {
        'vod_id': str(item.get('vod_id', '')),
        'vod_name': item.get('vod_name', ''),
        'type_id': mapped if mapped is not None else 0,
        'type_name': item.get('type_name', ''),
        'vod_year': str(item.get('vod_year', '') or ''),
        'vod_area': item.get('vod_area', '') or '',
        'vod_score': str(item.get('vod_score', '') or ''),
        'vod_remarks': item.get('vod_remarks', '') or '',
        'vod_content': item.get('vod_content', '') or item.get('vod_blurb', '') or '',
        'vod_pic': item.get('vod_pic', '') or '',
        'vod_play_url': item.get('vod_play_url', '') or '',
        '_src': src['id'], '_src_name': src['name'],
        '_raw_tid': raw_tid,
    }

def probe_source(api):
    """测试采集源连通性，返回其分类列表与样本条目（供类型映射 UI 使用）。"""
    out = {'ok': False, 'types': [], 'sample': [], 'total': 0, 'msg': ''}
    errs = []
    try:
        r = collect_query(api, {'ac': 'list'}, timeout=15)
        cls = r.get('class') or []
        if cls:
            out['types'] = [{'type_id': c.get('type_id'), 'type_name': c.get('type_name')} for c in cls]
            out['ok'] = True
    except Exception as e:
        errs.append('分类接口: %s' % e)
    try:
        r2 = collect_query(api, {'ac': 'videolist', 'pg': 1}, timeout=15)
        out['sample'] = [{'vod_id': v.get('vod_id'), 'vod_name': v.get('vod_name'),
                          'type_id': v.get('type_id'), 'type_name': v.get('type_name')}
                         for v in (r2.get('list') or [])[:8]]
        out['total'] = r2.get('total') or 0
        out['ok'] = True
    except Exception as e:
        errs.append('列表接口: %s' % e)
    out['msg'] = ' / '.join(errs)
    return out

def aggregate_search(kw, limit=24):
    """本地片库 + 所有已启用采集源 聚合搜索。"""
    local = Api.search({'wd': [kw]}).get('list', [])[:limit]
    for v in local:
        v['_src'] = 'local'; v['_src_name'] = '内置片库'
    remote, srcs, details = [], [], []
    for src in Api.sources().get('slice_sources', []):
        if src.get('kind') != 'slice' or not src.get('enabled') or not src.get('api'):
            continue
        srcs.append(src['name'])
        try:
            r = collect_query(src['api'], {'ac': 'videolist', 'wd': kw, 'pg': 1}, timeout=12)
            got = r.get('list') or []
            for it in got:
                remote.append(norm_vod(it, src))
            details.append({'name': src['name'], 'count': len(got), 'error': ''})
        except Exception as e:
            details.append({'name': src['name'], 'count': 0, 'error': str(e)})
            continue
    return {'code': 1, 'wd': kw, 'local': local,
            'remote': remote[:limit * 2], 'sources': srcs, 'details': details,
            'total': len(local) + len(remote)}

def aggregate_detail(src_id, vod_id):
    """从指定采集源取详情（含分集播放地址）。"""
    src = next((s for s in Api.sources().get('slice_sources', []) if s['id'] == src_id), None)
    if not src:
        return {'code': 0, 'msg': '采集源不存在'}
    try:
        r = collect_query(src['api'], {'ac': 'videolist', 'ids': vod_id}, timeout=15)
    except Exception as e:
        return {'code': 0, 'msg': '采集源请求失败: %s' % e}
    items = r.get('list') or []
    if not items:
        return {'code': 0, 'msg': '资源不存在'}
    v = norm_vod(items[0], src)
    v['episodes'] = norm_play_url(v.get('vod_play_url'))
    return {'code': 1, 'data': v, 'episodes': v['episodes']}

def source_lines(name, timeout=6):
    """给定片名，向所有已启用采集源查询同名资源，返回「线路」列表（含分集与测速）。"""
    lines = []
    for src in Api.sources().get('slice_sources', []):
        if src.get('kind') != 'slice' or not src.get('enabled') or not src.get('api'):
            continue
        try:
            t0 = time.time()
            r = collect_query(src['api'], {'ac': 'videolist', 'wd': name, 'pg': 1}, timeout=timeout)
            ms = int((time.time() - t0) * 1000)
            items = r.get('list') or []
            best = next((it for it in items
                         if (it.get('vod_name') or '').strip() == name.strip()), None)
            if best is None and items:
                best = items[0]
            if not best:
                continue
            eps = norm_play_url(best.get('vod_play_url'))
            if not eps:
                continue
            lines.append({
                'src': src['id'], 'src_name': src['name'],
                'vod_id': str(best.get('vod_id')), 'vod_name': best.get('vod_name') or name,
                'type_name': best.get('type_name') or '', 'vod_pic': best.get('vod_pic') or '',
                'remarks': best.get('vod_remarks') or '', 'ms': ms,
                'priority': int(src.get('priority') or 0),
                'episodes': eps,
            })
        except Exception:
            continue
    # 优先级高者优先；同级按响应快慢
    lines.sort(key=lambda x: (-x['priority'], x['ms']))
    for i, ln in enumerate(lines):
        ln['line'] = i + 1
    return lines

def speedtest_sources():
    """对全部已启用采集源做延迟探测，用于自动选源排序。"""
    out = []
    for src in Api.sources().get('slice_sources', []):
        if src.get('kind') != 'slice' or not src.get('api'):
            continue
        try:
            t0 = time.time()
            collect_query(src['api'], {'ac': 'list'}, timeout=6)
            ms = int((time.time() - t0) * 1000)
            out.append({'id': src['id'], 'name': src['name'], 'ms': ms, 'ok': True,
                        'level': '快' if ms < 400 else ('中' if ms < 1200 else '慢')})
        except Exception as e:
            out.append({'id': src['id'], 'name': src['name'], 'ms': -1, 'ok': False,
                        'level': '失效', 'msg': str(e)[:60]})
    out.sort(key=lambda x: (not x['ok'], x['ms'] if x['ms'] >= 0 else 9e9))
    return out

# —— 内置演示采集源（标准采集 JSON），用于离线端到端验证对接流程 ——
MOCK_TYPES = [
    {'type_id': 29, 'type_pid': 0, 'type_name': '国产动漫'},
    {'type_id': 30, 'type_pid': 0, 'type_name': '日本动漫'},
    {'type_id': 31, 'type_pid': 0, 'type_name': '欧美动漫'},
    {'type_id': 32, 'type_pid': 0, 'type_name': '电影'},
    {'type_id': 33, 'type_pid': 0, 'type_name': '纪录片'},
]
MOCK_MAP = {34: 31, 12: 32, 43: 33}

def mock_collect(q, base=''):
    """模拟一个第三方采集站，返回标准苹果 CMS JSON（播放地址为绝对 URL）。"""
    ac = (q.get('ac', ['list'])[0] or 'list')
    wd = (q.get('wd', [''])[0] or '').strip()
    t = (q.get('t', [''])[0] or '')
    pg = int(q.get('pg', ['1'])[0] or 1)
    if ac == 'list':
        return {'code': 1, 'msg': '分类', 'class': MOCK_TYPES, 'list': []}
    items = []
    for v in Api.library():
        tid = MOCK_MAP.get(v['type_id'], 31)
        if t and str(tid) != str(t):
            continue
        if wd:
            k = wd.lower()
            hay = ' '.join([v['vod_name'], v.get('vod_content', ''), v.get('type_name', ''),
                            ' '.join(v.get('vod_tags', []))]).lower()
            if k not in hay:
                continue
        eps = '#'.join('%s$%s' % (e['name'], (base + e['url']) if e['url'].startswith('/') else e['url'])
                       for e in v['episodes'])
        items.append({
            'vod_id': v['vod_id'], 'vod_name': v['vod_name'],
            'type_id': tid, 'type_name': next(x['type_name'] for x in MOCK_TYPES if x['type_id'] == tid),
            'vod_pic': '', 'vod_year': v['vod_year'], 'vod_area': v['vod_area'],
            'vod_score': v['vod_score'], 'vod_remarks': v['vod_remarks'],
            'vod_play_from': 'mock', 'vod_play_url': eps,
            'vod_content': v['vod_content'],
        })
    limit = 20
    start = (pg - 1) * limit
    return {'code': 1, 'msg': '数据列表', 'page': pg,
            'pagecount': max(1, (len(items) + limit - 1) // limit),
            'limit': limit, 'total': len(items), 'list': items[start:start + limit],
            'class': MOCK_TYPES}

def sniff_deep(url, depth=2):
    """抓取网页并(递归)提取媒体直链与 iframe —— 服务端嗅探实现。"""
    seen, media, iframes, pages = set(), [], [], []
    def walk(u, d):
        if u in seen or d < 0 or len(seen) > 8:
            return
        seen.add(u); pages.append(u)
        try:
            html = http_get(u, timeout=10)
        except Exception:
            return
        for m in MEDIA_RE.findall(html):
            if m not in media:
                media.append(m)
        for f in IFRAME_RE.findall(html):
            f = f.strip()
            if f.startswith('//'):
                f = 'https:' + f
            elif f.startswith('/'):
                p = urlparse(u)
                f = '%s://%s%s' % (p.scheme, p.netloc, f)
            if f.startswith('http') and f not in iframes:
                iframes.append(f)
        for f in iframes[-6:]:
            walk(f, d - 1)
    walk(url, depth)
    return {'playUrl': media[0] if media else '', 'mediaList': media[:30],
            'iframes': iframes[:12], 'pages': pages}

# --------------------------------------------------------------------------
class Handler(BaseHTTPRequestHandler):
    server_version = 'VidNest/1.0'
    protocol_version = 'HTTP/1.1'

    def log_message(self, fmt, *args):
        pass  # 安静模式

    # ---------- helpers ----------
    def _send(self, code, body, ctype='application/json; charset=utf-8', extra=None, cache='no-store'):
        if isinstance(body, (dict, list)):
            body = json.dumps(body, ensure_ascii=False).encode()
        elif isinstance(body, str):
            body = body.encode()
        self.send_response(code)
        self.send_header('Content-Type', ctype)
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Headers', 'Authorization,Content-Type')
        self.send_header('Access-Control-Allow-Methods', 'GET,POST,OPTIONS')
        self.send_header('Cache-Control', cache)
        if extra:
            for k, v in extra.items():
                self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def _json_body(self):
        try:
            n = int(self.headers.get('Content-Length', 0) or 0)
            return json.loads(self.rfile.read(n).decode() or '{}')
        except Exception:
            return {}

    def _uid(self):
        auth = self.headers.get('Authorization', '')
        if auth.startswith('Bearer '):
            return verify_token(auth[7:])
        return None

    def _q(self):
        return parse_qs(urlparse(self.path).query)

    # ---------- routing ----------
    def do_OPTIONS(self):
        self._send(204, b'')

    def do_GET(self):
        p = urlparse(self.path).path
        q = self._q()
        try:
            if p == '/healthz':
                return self._send(200, {'ok': True, 'app': APP_NAME, 'version': APP_VERSION})
            if p == '/download/vidnest-single.py':
                # 方便在手机浏览器里直接下载「单文件部署版」，再上传到 GitHub
                fp = os.path.join(ROOT, 'vidnest-single.py')
                if not os.path.isfile(fp):
                    return self._send(404, 'not found: 请先生成 vidnest-single.py')
                with open(fp, 'rb') as fh:
                    body = fh.read()
                return self._send(200, body, 'application/octet-stream', cache='no-store',
                                  extra={'Content-Disposition':
                                         'attachment; filename="vidnest-single.py"'})
            if p.startswith('/mock/collect'):
                # 反代/隧道场景下用 X-Forwarded-Proto + Host 还原真实外网地址
                proto = self.headers.get('X-Forwarded-Proto') or 'http'
                host = self.headers.get('Host') or ('127.0.0.1:%d' % self.server.server_port)
                return self._send(200, mock_collect(q, '%s://%s' % (proto, host)))
            if p.startswith('/api/'):
                return self.api_get(p, q)
            if p.startswith('/poster/'):
                return self.poster(p)
            return self.static(p)
        except Exception as e:
            return self._send(500, {'code': 0, 'msg': 'server error: %s' % e})

    def do_POST(self):
        p = urlparse(self.path).path
        try:
            if p.startswith('/api/'):
                return self.api_post(p)
            return self._send(404, {'code': 0, 'msg': 'not found'})
        except Exception as e:
            return self._send(500, {'code': 0, 'msg': 'server error: %s' % e})

    # ---------- API: GET ----------
    def api_get(self, p, q):
        A = Api
        if p == '/api/v1/update':
            return self._send(200, {'code': '00000', 'msg': 'success', 'data': {
                'version': APP_VERSION, 'buildNumber': BUILD_NUMBER,
                'updateInfo': '1. 全新「影巢」聚合框架\n2. 新增采集源 / 嗅探源管理\n3. 弹幕支持发送与开关\n4. 新增追番与云端进度同步',
                'androidUrl': '#', 'iosUrl': '#', 'forceUpdate': False}})
        if p == '/api/v1/home':
            return self._send(200, {'code': 1, 'data': A.home()})
        if p == '/api/v1/resource/types':
            return self._send(200, {'code': 1, 'list': A.types()})
        if p == '/api/v1/resources':
            return self._send(200, A.list_resources(q))
        if p == '/api/v1/search':
            return self._send(200, A.search(q))
        if p == '/api/v1/resources/byids':
            ids = [int(x) for x in re.findall(r'\d+', q.get('ids', [''])[0])]
            return self._send(200, A.byids(ids))
        if p == '/api/v1/hotwords':
            return self._send(200, {'code': 1, 'list': A.hotwords()})
        if p == '/api/v1/net':
            port = self.server.server_port
            proto = self.headers.get('X-Forwarded-Proto') or 'http'
            host = self.headers.get('Host') or ('127.0.0.1:%d' % port)
            v6 = global_ipv6()
            return self._send(200, {'code': 1,
                                    'port': port,
                                    'current': '%s://%s' % (proto, host),
                                    'lan': ['http://%s:%d' % (i, port) for i in lan_ips()],
                                    'ipv6': ('http://[%s]:%d' % (v6, port)) if v6 else '',
                                    'public': os.environ.get('PUBLIC_URL', '')})
        if p == '/api/v1/poster':
            # 为采集源条目动态生成海报
            title = q.get('t', ['VidNest'])[0] or 'VidNest'
            sub = q.get('s', [''])[0]
            svg = poster_svg({'vod_id': abs(hash(title)) % 8, 'vod_name': title,
                              'type_name': sub, 'vod_year': '', 'vod_score': ''})
            return self._send(200, svg, 'image/svg+xml', cache='public, max-age=3600')
        if p == '/api/v1/source/list':
            s = A.sources()
            return self._send(200, {'code': 1, 'list': s['slice_sources'] + s['sniff_sources'],
                                    'mappings': s['mappings']})
        if p == '/api/v1/aggregate/search':
            kw = (q.get('wd', [''])[0] or '').strip()
            if not kw:
                return self._send(400, {'code': 0, 'msg': '缺少 wd'})
            return self._send(200, aggregate_search(kw))
        if p == '/api/v1/aggregate/detail':
            sid = q.get('src', [''])[0]; vid = q.get('id', [''])[0]
            return self._send(200, aggregate_detail(sid, vid))
        if p == '/api/v1/aggregate/lines':
            nm = (q.get('name', [''])[0] or '').strip()
            if not nm:
                return self._send(400, {'code': 0, 'msg': '缺少 name'})
            lines = source_lines(nm)
            return self._send(200, {'code': 1, 'name': nm, 'lines': lines,
                                    'count': len(lines)})
        if p == '/api/v1/source/proxy':
            # 服务端代理抓取：绕开浏览器跨域限制，供嗅探/调试使用（仅本地演示）
            u = q.get('url', [''])[0]
            if not u.startswith('http'):
                return self._send(400, {'code': 0, 'msg': 'url 不合法'})
            try:
                return self._send(200, {'code': 1, 'text': http_get(u, timeout=10)[:200000]})
            except Exception as e:
                return self._send(200, {'code': 0, 'msg': '代理失败: %s' % e})
        if p == '/api/v1/resource/adapters':
            s = A.sources()
            return self._send(200, {'code': 1, 'adapters': s['slice_sources'],
                                    'sniff': s['sniff_sources'], 'mappings': s['mappings']})
        m = re.match(r'^/api/v1/resource/(\d+)$', p)
        if m:
            return self._send(200, A.detail(m.group(1)))
        if p == '/api/v1/resource/danmakus':
            vid = q.get('vid', ['0'])[0]; ep = q.get('ep', ['0'])[0]
            d = load('danmaku', {}).get('%s-%s' % (vid, ep), [])
            if not d:
                d = self._seed_danmaku(vid, ep)
            return self._send(200, {'code': 1, 'list': d})
        if p == '/api/v1/resource/sniff':
            url = q.get('url', [''])[0]
            if not url: return self._send(400, {'code': 0, 'msg': '缺少 url'})
            try:
                return self._send(200, {'code': 1, 'data': sniff_page(url)})
            except Exception as e:
                return self._send(200, {'code': 0, 'msg': '嗅探失败: %s' % e})
        if p == '/api/v1/history':
            uid = self._uid() or 'guest'
            return self._send(200, {'code': 1, 'list': load('history', {}).get(uid, [])})
        if p == '/api/v1/progress':
            uid = self._uid() or 'guest'
            return self._send(200, {'code': 1, 'list': load('progress', {}).get(uid, {})})
        if p == '/api/v1/user/collects':
            uid = self._uid() or 'guest'
            return self._send(200, {'code': 1, 'list': load('collects', {}).get(uid, [])})
        if p == '/api/v1/user/me':
            uid = self._uid()
            if not uid: return self._send(401, {'code': 0, 'msg': '未登录'})
            u = load('users', {}).get(uid)
            if not u: return self._send(401, {'code': 0, 'msg': '用户不存在'})
            return self._send(200, {'code': 1, 'user': {k: u[k] for k in ('uid', 'nick', 'isVip', 'vipExpire')}})
        if p == '/api/v1/user/messages':
            return self._send(200, {'code': 1, 'list': load('messages', {}).get('public', [
                {'id': 1, 'title': '欢迎使用影巢 VidNest', 'body': '这是一个参考 MTVF / AFAN 架构自建的演示应用。', 'time': '2026-09-01'},
                {'id': 2, 'title': '播放源说明', 'body': '可在「播放源」页添加采集源或嗅探源。', 'time': '2026-09-02'},
            ])})
        return self._send(404, {'code': 0, 'msg': '接口不存在: %s' % p})

    def _seed_danmaku(self, vid, ep):
        base = [('这个画质也太顶了吧', 6, '#ff5c8a'), ('开源动画就是香', 8, '#ffffff'),
                ('弹幕测试成功 🎉', 10, '#7ee787'), ('前方高能', 14, '#ffd166'),
                ('VidNest 顶起来', 18, '#60a5fa')]
        key = '%s-%s' % (vid, ep)
        store = load('danmaku', {})
        lst = [{'id': i + 1, 'text': t, 'time': tm, 'color': c, 'mode': 0} for i, (t, tm, c) in enumerate(base)]
        store[key] = lst
        save('danmaku', store)
        return lst

    # ---------- API: POST ----------
    def api_post(self, p):
        b = self._json_body()
        if p == '/api/v1/login':
            nick = (b.get('nick') or b.get('username') or '').strip()
            pw = b.get('password') or ''
            if not nick or not pw:
                return self._send(400, {'code': 0, 'msg': '账号或密码为空'})
            users = load('users', {})
            u = next((u for u in users.values() if u['nick'] == nick), None)
            if u is None:  # 注册
                uid = uuid.uuid4().hex[:12]
                u = {'uid': uid, 'nick': nick, 'pw': hash_pw(pw), 'isVip': False,
                     'vipExpire': '', 'created': int(time.time())}
                users[uid] = u; save('users', users)
            elif not check_pw(pw, u['pw']):
                return self._send(401, {'code': 0, 'msg': '密码错误'})
            return self._send(200, {'code': 1, 'accessToken': make_token(u['uid']),
                                    'refreshToken': make_token(u['uid']),
                                    'user': {k: u[k] for k in ('uid', 'nick', 'isVip', 'vipExpire')}})
        if p == '/api/v1/auth/public/refreshToken':
            uid = self._uid()
            if not uid: return self._send(401, {'code': 0, 'msg': '刷新失败'})
            return self._send(200, {'code': 1, 'accessToken': make_token(uid)})
        if p == '/api/v1/user/invite':
            uid = self._uid()
            if not uid: return self._send(401, {'code': 0, 'msg': '未登录'})
            code = (b.get('inviteCode') or '').strip()
            if not re.match(r'^[A-Z0-9]{6,16}$', code.upper()):
                return self._send(400, {'code': 0, 'msg': '邀请码格式不正确'})
            users = load('users', {}); u = users.get(uid)
            u['isVip'] = True
            u['vipExpire'] = time.strftime('%Y-%m-%d', time.localtime(time.time() + 30 * 86400))
            save('users', users)
            return self._send(200, {'code': 1, 'msg': '兑换成功，获得 30 天会员', 'user': u})
        if p == '/api/v1/resource/danmaku/save':
            vid = str(b.get('vid')); ep = str(b.get('ep', 0))
            text = (b.get('text') or '').strip()[:120]
            if not text: return self._send(400, {'code': 0, 'msg': '弹幕为空'})
            store = load('danmaku', {}); key = '%s-%s' % (vid, ep)
            lst = store.get(key) or self._seed_danmaku(vid, ep)
            item = {'id': len(lst) + 1, 'text': text, 'time': float(b.get('time', 0)),
                    'color': b.get('color', '#ffffff'), 'mode': 0}
            lst.append(item); store[key] = lst; save('danmaku', store)
            return self._send(200, {'code': 1, 'data': item})
        if p == '/api/v1/history':
            uid = self._uid() or 'guest'
            h = load('history', {}); lst = h.get(uid, [])
            item = b.get('item') or {}
            item['time'] = int(time.time())
            lst = [x for x in lst if x.get('vod_id') != item.get('vod_id')]
            lst.insert(0, item); h[uid] = lst[:200]; save('history', h)
            return self._send(200, {'code': 1, 'list': h[uid]})
        if p == '/api/v1/history/clear':
            uid = self._uid() or 'guest'
            h = load('history', {}); h[uid] = []; save('history', h)
            return self._send(200, {'code': 1, 'list': []})
        if p == '/api/v1/history/remove':
            uid = self._uid() or 'guest'
            h = load('history', {}); vid = b.get('vod_id')
            h[uid] = [x for x in h.get(uid, []) if x.get('vod_id') != vid]; save('history', h)
            return self._send(200, {'code': 1, 'list': h[uid]})
        if p.startswith('/api/v1/progress/resource/'):
            uid = self._uid() or 'guest'
            vid = p.rsplit('/', 1)[-1]
            pr = load('progress', {}); m = pr.get(uid, {})
            m[vid] = {'pos': float(b.get('pos', 0)), 'dur': float(b.get('dur', 0)),
                      'ep': b.get('ep', 0), 'time': int(time.time())}
            pr[uid] = m; save('progress', pr)
            return self._send(200, {'code': 1})
        if p == '/api/v1/user/collects':
            uid = self._uid() or 'guest'
            c = load('collects', {}); lst = c.get(uid, [])
            vid = b.get('vod_id'); action = b.get('action', 'toggle')
            exists = any(x.get('vod_id') == vid for x in lst)
            if action == 'add' or (action == 'toggle' and not exists):
                if not exists:
                    lst.insert(0, {'vod_id': vid, 'name': b.get('name', ''), 'collect': True,
                                   'time': int(time.time())})
            else:
                lst = [x for x in lst if x.get('vod_id') != vid]
            c[uid] = lst; save('collects', c)
            return self._send(200, {'code': 1, 'collected': any(x.get('vod_id') == vid for x in lst),
                                    'list': lst})
        if p == '/api/v1/user/feedbacks':
            fb = load('feedbacks', []); b['time'] = int(time.time()); fb.append(b); save('feedbacks', fb)
            return self._send(200, {'code': 1, 'msg': '反馈已提交，感谢反馈！'})
        if p == '/api/v1/source/save':
            s = Api.sources()
            kind = b.get('kind', 'slice')
            if kind == 'slice':
                sid = b.get('id') or ('src' + uuid.uuid4().hex[:6])
                item = {'id': sid, 'name': b.get('name') or '未命名采集源',
                        'api': (b.get('api') or '').strip(), 'kind': 'slice',
                        'enabled': True, 'note': b.get('note') or '通用采集接口',
                        'mappings': b.get('mappings') or {}}
                s['slice_sources'] = [x for x in s['slice_sources'] if x['id'] != sid] + [item]
            elif kind == 'sniff':
                sid = b.get('id') or ('snf' + uuid.uuid4().hex[:6])
                item = {'id': sid, 'name': b.get('name') or '未命名嗅探源',
                        'script': b.get('script') or '', 'note': b.get('note') or 'JS 网页嗅探',
                        'kind': 'sniff', 'enabled': True}
                s['sniff_sources'] = [x for x in s['sniff_sources'] if x['id'] != sid] + [item]
            save('sources', s)
            cache_drop('sources')
            return self._send(200, {'code': 1, 'msg': '保存成功'})

        if p == '/api/v1/source/probe':
            api = (b.get('api') or '').strip()
            if not api.startswith('http'):
                return self._send(400, {'code': 0, 'msg': '请填写完整的接口地址'})
            return self._send(200, {'code': 1, 'data': probe_source(api)})

        if p == '/api/v1/source/sniff':
            u = (b.get('url') or '').strip()
            if not u.startswith('http'):
                return self._send(400, {'code': 0, 'msg': '请填写完整的网页地址'})
            try:
                return self._send(200, {'code': 1, 'data': sniff_deep(u)})
            except Exception as e:
                return self._send(200, {'code': 0, 'msg': '嗅探失败: %s' % e})

        if p == '/api/v1/source/delete':
            s = Api.sources()
            sid = b.get('id')
            s['slice_sources'] = [x for x in s['slice_sources'] if x['id'] != sid]
            s['sniff_sources'] = [x for x in s['sniff_sources'] if x['id'] != sid]
            save('sources', s)
            cache_drop('sources')
            return self._send(200, {'code': 1, 'msg': '已删除'})

        if p == '/api/v1/source/speedtest':
            return self._send(200, {'code': 1, 'list': speedtest_sources()})

        if p == '/api/v1/source/priority':
            s = Api.sources()
            sid = b.get('id')
            for x in s['slice_sources']:
                if x['id'] == sid:
                    x['priority'] = int(b.get('priority') or 0)
            save('sources', s)
            cache_drop('sources')
            return self._send(200, {'code': 1, 'msg': '已更新优先级'})

        if p == '/api/v1/source/toggle':
            s = Api.sources()
            sid = b.get('id')
            for coll in ('slice_sources', 'sniff_sources'):
                for x in s[coll]:
                    if x['id'] == sid:
                        x['enabled'] = bool(b.get('enabled', True))
            save('sources', s)
            cache_drop('sources')
            return self._send(200, {'code': 1, 'msg': '已更新'})
        return self._send(404, {'code': 0, 'msg': '接口不存在: %s' % p})

    # ---------- poster / static ----------
    def poster(self, p):
        m = re.match(r'^/poster/(\d+)\.svg$', p)
        if not m:
            return self._send(404, 'not found')
        vid = int(m.group(1))
        v = next((x for x in Api.library() if x['vod_id'] == vid), None)
        if not v:
            return self._send(404, 'not found')
        svg = cache_get('poster:%d' % vid, lambda: poster_svg(v))
        return self._send(200, svg, 'image/svg+xml',
                          cache='public, max-age=604800, immutable')

    def static(self, p):
        if p == '/' or p == '':
            p = '/index.html'
        rel = unquote(p).lstrip('/')

        # —— 单文件部署版：优先使用内嵌资源（vidnest-single.py）——
        if rel in EMBEDDED:
            ctype, body = embedded_get(rel)
            return self.serve_bytes(rel, ctype, body)

        full = os.path.normpath(os.path.join(WEB, rel))
        if not full.startswith(WEB):
            return self._send(403, 'forbidden')
        if not os.path.isfile(full):
            full = os.path.join(WEB, 'index.html')          # SPA fallback
        ext = os.path.splitext(full)[1].lower()
        with open(full, 'rb') as f:
            body = f.read()
        return self.serve_bytes(full, MIME.get(ext, 'application/octet-stream'), body)

    def serve_bytes(self, name, ctype, body):
        """统一发送响应，含 HTTP Range（视频拖动进度必需）。"""
        size = len(body)
        ext = os.path.splitext(name)[1].lower()
        cache = 'no-cache' if ext == '.html' else 'public, max-age=3600'
        if ext == '.mp4':
            cache = 'public, max-age=604800'

        rng = self.headers.get('Range')
        if rng:
            m = re.match(r'bytes=(\d*)-(\d*)', rng)
            if m:
                start = int(m.group(1)) if m.group(1) else 0
                end = int(m.group(2)) if m.group(2) else size - 1
                end = min(end, size - 1)
                if start > end:
                    self.send_response(416)
                    self.send_header('Content-Range', 'bytes */%d' % size)
                    self.send_header('Content-Length', '0')
                    self.end_headers()
                    return
                length = end - start + 1
                self.send_response(206)
                self.send_header('Content-Type', ctype)
                self.send_header('Content-Length', str(length))
                self.send_header('Content-Range', 'bytes %d-%d/%d' % (start, end, size))
                self.send_header('Accept-Ranges', 'bytes')
                self.send_header('Cache-Control', cache)
                self.send_header('Access-Control-Allow-Origin', '*')
                self.end_headers()
                self.wfile.write(body[start:start + length])
                return

        self._send(200, body, ctype, cache=cache, extra={'Accept-Ranges': 'bytes'})

# --------------------------------------------------------------------------
class Server(ThreadingHTTPServer):
    """关键：默认 request_queue_size 只有 5，浏览器并发拉取海报时会被排队/重试，
    表现为「打开很慢」。这里加大 backlog 并开启守护线程。"""
    daemon_threads = True
    allow_reuse_address = True
    request_queue_size = 128

class Server6(Server):
    """IPv6 双栈监听：手机流量网络多为原生 IPv6（无 NAT），
    因此全球 IPv6 地址可被其他设备直接访问，**无需任何隧道**。"""
    address_family = socket.AF_INET6

    def server_bind(self):
        try:
            self.socket.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)  # 同端口同时收 IPv4
        except Exception:
            pass
        super().server_bind()

def make_server(port, handler):
    try:
        return Server6(('::', port), handler), 'IPv4+IPv6 双栈 [::]:%d' % port
    except OSError as e:
        return Server(('0.0.0.0', port), handler), '仅 IPv4 0.0.0.0:%d（IPv6 不可用：%s）' % (port, e)

def global_ipv6():
    """取本机用于对外通信的全球 IPv6 地址（fe80 链路本地不算）。"""
    try:
        s = socket.socket(socket.AF_INET6, socket.SOCK_DGRAM)
        s.connect(('2400:3200::1', 53))       # 阿里公共 DNS 的 IPv6
        ip = s.getsockname()[0].split('%')[0]
        s.close()
        if ':' in ip and not ip.startswith('fe80') and ip not in ('::1', ''):
            return ip
    except Exception:
        pass
    return ''

def lan_ips():
    """探测本机可用于对外访问的 IPv4 地址（局域网/热点）。"""
    ips = set()
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(('8.8.8.8', 80))
        ips.add(s.getsockname()[0])
        s.close()
    except Exception:
        pass
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            a = info[4][0]
            if not a.startswith('127.'):
                ips.add(a)
    except Exception:
        pass
    return sorted(ips)

def main():
    import sys
    # 支持 PORT 环境变量（云平台/容器），也支持命令行参数
    port = int(os.environ.get('PORT') or (sys.argv[1] if len(sys.argv) > 1 else 8000))
    ensure_seed()
    # 把采集源里的 SELF 占位符替换为真实地址（内置演示采集源需要绝对 URL）
    _s = load('sources', seed_sources())
    _changed = False
    for x in _s.get('slice_sources', []):
        if isinstance(x.get('api'), str) and x['api'].startswith('SELF'):
            x['api'] = 'http://127.0.0.1:%d' % port + x['api'][4:]
            _changed = True
    if _changed:
        save('sources', _s)
    cache_drop('sources')
    srv, listen = make_server(port, Handler)
    print('🎬 %s v%s 已启动' % (APP_NAME, APP_VERSION))
    print('   监听    : %s' % listen)
    print('   本机    : http://127.0.0.1:%d' % port)
    for ip in lan_ips():
        print('   局域网  : http://%s:%d' % (ip, port))
    v6 = global_ipv6()
    if v6:
        print('   公网IPv6: http://[%s]:%d   ← 手机流量 / 其他 IPv6 网络可直接访问' % (v6, port))
    if os.environ.get('PUBLIC_URL'):
        print('   公网    : %s' % os.environ['PUBLIC_URL'])
    print('   健康检查: /healthz')
    print('   片库 %d 部 · 采集源/嗅探源已就绪' % len(Api.library()))
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass

if __name__ == '__main__':
    main()
